import React, { useState, useEffect, memo } from 'react';
import type { Game } from '../types';
import { getSchedule } from '../services/geminiService';

interface GameScheduleProps {
  sport: string;
  selectedGame: Game | null;
  onSelectGame: (game: Game) => void;
}

export const GameSchedule: React.FC<GameScheduleProps> = memo(({ sport, selectedGame, onSelectGame }) => {
  const [games, setGames] = useState<Game[]>([]);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);

  const fetchGames = async () => {
    setIsLoading(true);
    setError(null);
    try {
      const fetchedGames = await getSchedule(sport);
      setGames(fetchedGames);
      if (fetchedGames.length === 0) {
        setError(`No games found for ${sport} today.`);
      }
    } catch (err) {
      setError('Failed to load schedule. Retrying...');
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchGames();
  }, [sport]);

  if (isLoading) {
    return (
      <div className="flex flex-col items-center justify-center py-12 space-y-4">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-amber-500"></div>
        <p className="text-orange-50/50 text-sm animate-pulse">Locating live feeds & odds...</p>
      </div>
    );
  }

  if (error) {
    return (
        <div className="text-center py-8">
            <p className="text-rose-400 mb-4">{error}</p>
            <button 
                onClick={fetchGames}
                className="text-sm bg-zinc-800 hover:bg-zinc-700 text-orange-50 px-4 py-2 rounded-full transition-colors"
            >
                Refresh
            </button>
        </div>
    );
  }

  return (
    <div className="space-y-4 w-full">
      <div className="flex justify-between items-center mb-2 px-2">
        <div className="text-xs text-stone-500 uppercase tracking-wider font-semibold">
           Live & Today's Games
        </div>
        <button 
            onClick={fetchGames} 
            className="text-xs text-amber-500 hover:text-amber-400 flex items-center gap-1 transition-colors"
        >
            <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor" className="w-3 h-3">
                <path fillRule="evenodd" d="M15.312 11.424a5.5 5.5 0 01-9.201 2.466l-.312-.311h2.433a.75.75 0 000-1.5H3.989a.75.75 0 00-.75.75v4.242a.75.75 0 001.5 0v-2.43l.31.31a7 7 0 0011.712-3.138.75.75 0 00-1.449-.39zm1.23-3.723a.75.75 0 00.219-.53V2.929a.75.75 0 00-1.5 0v2.433l-.31-.31a7 7 0 00-11.712 3.138.75.75 0 001.449.39 5.5 5.5 0 019.201-2.466l.312.312h-2.433a.75.75 0 000 1.5h4.242z" clipRule="evenodd" />
            </svg>
            Live Update
        </button>
      </div>

      <div className="grid gap-3 max-h-[400px] overflow-y-auto pr-2 custom-scrollbar">
        {games.map((game) => {
          const isSelected = selectedGame?.id === game.id;
          const isLive = game.status === 'Live';

          // Detect advanced live states (Q3, Q4, OT, etc.) for highlighting
          // FIX: Added null check (game.time || '') to prevent crash if time is null
          const timeText = (game.time || '').toLowerCase();
          const isLateGame = timeText.includes('q3') || timeText.includes('q4') || timeText.includes('3rd') || timeText.includes('4th') || timeText.includes('ot') || timeText.includes('overtime');

          return (
            <button
              key={game.id}
              onClick={() => onSelectGame(game)}
              className={`relative group w-full text-left p-4 rounded-xl border transition-all duration-200 ${
                isSelected
                  ? 'bg-zinc-900 border-amber-500 shadow-[0_0_15px_rgba(245,158,11,0.2)]'
                  : isLive
                    ? 'bg-gradient-to-br from-[#1a0505] to-black border-red-900/50 shadow-[inset_0_0_20px_rgba(220,38,38,0.05)] hover:border-red-700'
                    : 'bg-black border-zinc-800 hover:border-zinc-600 hover:bg-zinc-900'
              }`}
            >
              {isLive && (
                <span className={`absolute top-0 right-0 px-3 py-1 rounded-bl-xl rounded-tr-xl border-l border-b z-10 flex items-center gap-2 ${
                    isLateGame 
                        ? 'bg-amber-500/20 border-amber-500/40 text-amber-400' 
                        : 'bg-red-600/20 border-red-500/40 text-red-500'
                }`}>
                    <span className="relative flex h-2 w-2">
                        <span className={`animate-ping absolute inline-flex h-full w-full rounded-full opacity-75 ${isLateGame ? 'bg-amber-500' : 'bg-red-500'}`}></span>
                        <span className={`relative inline-flex rounded-full h-2 w-2 ${isLateGame ? 'bg-amber-500' : 'bg-red-500'}`}></span>
                    </span>
                    <span className="text-[10px] font-black tracking-wider uppercase">
                        {isLateGame ? 'Crunch Time' : 'Live'}
                    </span>
                </span>
              )}

              <div className="flex items-center justify-between gap-4">
                {/* Home Team */}
                <div className="flex-1 flex flex-col items-center gap-2">
                    <img 
                        src={`https://avatar.vercel.sh/${encodeURIComponent(game.homeTeam)}.png?size=64`} 
                        alt={game.homeTeam}
                        className="w-10 h-10 rounded-full bg-zinc-800 border border-zinc-700 shadow-md p-0.5"
                    />
                    <span className={`text-sm font-bold text-center leading-tight ${isSelected ? 'text-white' : 'text-stone-300'}`}>
                        {game.homeTeam}
                    </span>
                </div>

                {/* VS / Score / Time */}
                <div className="flex flex-col items-center justify-center w-28">
                   {isLive && game.score ? (
                        <div className="flex flex-col items-center gap-1">
                            <div className="text-xl font-mono font-black text-white tracking-widest drop-shadow-md">
                                {game.score}
                            </div>
                            <span className={`text-[10px] font-bold px-2.5 py-0.5 rounded-full uppercase tracking-wider border shadow-lg ${
                                isLateGame 
                                    ? 'bg-amber-500 text-black border-amber-400 animate-pulse' 
                                    : 'bg-red-600 text-white border-red-500'
                            }`}>
                                {game.time}
                            </span>
                        </div>
                   ) : (
                        <div className="flex flex-col items-center">
                            <span className="text-xs font-bold text-stone-600 mb-1">VS</span>
                            <span className="text-[10px] text-stone-400 font-medium uppercase text-center bg-zinc-800/80 px-2 py-0.5 rounded">
                                {game.date === 'Today' ? game.time : `${game.date}`}
                            </span>
                        </div>
                   )}
                </div>

                {/* Away Team */}
                <div className="flex-1 flex flex-col items-center gap-2">
                    <img 
                        src={`https://avatar.vercel.sh/${encodeURIComponent(game.awayTeam)}.png?size=64`} 
                        alt={game.awayTeam}
                        className="w-10 h-10 rounded-full bg-zinc-800 border border-zinc-700 shadow-md p-0.5"
                    />
                    <span className={`text-sm font-bold text-center leading-tight ${isSelected ? 'text-white' : 'text-stone-300'}`}>
                        {game.awayTeam}
                    </span>
                </div>
              </div>

              {/* Odds Footer */}
              <div className={`mt-3 pt-3 flex flex-wrap justify-center items-center gap-3 border-t ${isLive ? 'border-white/10' : 'border-zinc-800'}`}>
                  {(game.odds?.spread || game.odds?.total) ? (
                    <>
                        {game.odds.spread && (
                            <span className={`text-[11px] font-mono px-1.5 py-0.5 rounded border ${isLive ? 'text-amber-300 bg-amber-900/20 border-amber-500/20' : 'text-amber-400 bg-amber-900/10 border-amber-900/20'}`}>
                                {game.odds.spread}
                            </span>
                        )}
                        {game.odds.total && (
                            <span className="text-[11px] font-mono text-stone-400 bg-zinc-800 px-1.5 py-0.5 rounded border border-zinc-700">
                                {game.odds.total}
                            </span>
                        )}
                        {game.odds.moneyline && (
                            <span className="text-[11px] font-mono text-stone-500">
                                ML: {game.odds.moneyline}
                            </span>
                        )}
                    </>
                  ) : (
                     <span className="text-[10px] text-zinc-600 italic">Odds waiting...</span>
                  )}
              </div>
            </button>
          );
        })}
      </div>
    </div>
  );
});

import React, { memo, useState, useMemo } from 'react';
import type { Prediction, ConfidenceLevel, OddsFormat, PropBet } from '../types';
import { AnalyticsIcon, PlusIcon, CheckIcon, SearchIcon, DoubleCheckIcon, SendIcon } from './Icons';

interface PredictionDisplayProps {
  prediction: Prediction;
  oddsFormat: OddsFormat;
  onAnalyzeProp?: (prop: PropBet) => void;
  pickSlip?: PropBet[];
  onTogglePick?: (prop: PropBet) => void;
  onSearchPlayer?: (player: string) => void;
}

const confidenceStyles: Record<string, { bg: string; text: string; border: string }> = {
    High: { bg: 'bg-green-900/50', text: 'text-green-300', border: 'border-green-800' },
    Medium: { bg: 'bg-amber-900/40', text: 'text-amber-300', border: 'border-amber-700' },
    Low: { bg: 'bg-rose-900/50', text: 'text-rose-300', border: 'border-rose-800' },
};

const convertAmericanToDecimal = (americanOdds: string): string => {
    const odds = parseInt(americanOdds, 10);
    if (isNaN(odds)) return americanOdds;

    let decimalOdds: number;
    if (odds > 0) {
        decimalOdds = (odds / 100) + 1;
    } else {
        decimalOdds = (100 / Math.abs(odds)) + 1;
    }
    return decimalOdds.toFixed(2);
};

// Helper to parse injury string
const parseInjury = (injuryString: string) => {
    // FIX: Guard clause for null/undefined injuryString
    if (!injuryString) return { player: 'Unknown', status: 'Report', reason: '' };

    // Expected format: "Player Name (Status) - Reason"
    // Regex handles optional reason part
    const match = injuryString.match(/^(.*?)\s*\((.*?)\)(?:\s*-\s*(.*))?$/);
    if (match) {
        return {
            player: match[1].trim(),
            status: match[2].trim(),
            reason: match[3] ? match[3].trim() : ''
        };
    }
    // Fallback if format doesn't match
    return { player: injuryString, status: 'Report', reason: '' };
};

const getStatusColor = (status: string) => {
    // FIX: Add check for null status
    const s = (status || '').toLowerCase();
    if (s.includes('out') || s.includes('ir') || s.includes('suspend') || s.includes('injure')) {
        return 'text-red-400 bg-red-900/20 border-red-500/30';
    }
    if (s.includes('doubt') || s.includes('question') || s.includes('day-to-day') || s.includes('gtd')) {
        return 'text-amber-400 bg-amber-900/20 border-amber-500/30';
    }
    if (s.includes('prob') || s.includes('available')) {
        return 'text-green-400 bg-green-900/20 border-green-500/30';
    }
    return 'text-slate-400 bg-zinc-800 border-zinc-700';
};

export const PredictionDisplay: React.FC<PredictionDisplayProps> = memo(({ prediction, oddsFormat, onAnalyzeProp, pickSlip = [], onTogglePick, onSearchPlayer }) => {
  const [typeFilter, setTypeFilter] = useState<'All' | 'MORE' | 'LESS'>('All');
  const [searchQuery, setSearchQuery] = useState<string>('');

  // Fallback to Medium if confidence key is missing or invalid
  const confidenceStyle = confidenceStyles[prediction.confidence] || confidenceStyles['Medium'];

  // Safe confidence percentage calculation
  const confidencePercentage = prediction.confidenceScore != null 
    ? (prediction.confidenceScore * 100).toFixed(0) 
    : 'N/A';

  const filteredProps = useMemo(() => {
    if (!prediction.props) return [];
    return prediction.props.filter(prop => {
        const matchesType = typeFilter === 'All' || prop.type === typeFilter;
        // FIX: Add null checks for prop.player and prop.stat
        const matchesSearch = (prop.player || '').toLowerCase().includes(searchQuery.toLowerCase()) || 
                              (prop.stat || '').toLowerCase().includes(searchQuery.toLowerCase());
        return matchesType && matchesSearch;
    });
  }, [prediction.props, typeFilter, searchQuery]);

  const formatOdds = (odds: string) => {
      if (!odds) return 'N/A';
      if (oddsFormat === 'Decimal') {
          return convertAmericanToDecimal(odds);
      }
      return odds;
  };

  return (
    <div className="space-y-6 w-full">
       {/* Winner Card */}
       <div className={`p-5 rounded-xl border ${confidenceStyle.border} ${confidenceStyle.bg} backdrop-blur-sm shadow-lg`}>
          <div className="flex justify-between items-start mb-3">
             <div className="flex items-center gap-4">
                 <img 
                    src={`https://ui-avatars.com/api/?name=${encodeURIComponent(prediction.winner)}&background=10b981&color=fff&size=128&bold=true`}
                    alt={prediction.winner}
                    className="w-16 h-16 rounded-full border-2 border-white/10 shadow-lg bg-zinc-800"
                 />
                 <div>
                    <span className="text-xs font-bold uppercase tracking-wider text-slate-400">Projected Winner</span>
                    <h2 className="text-2xl md:text-3xl font-black text-white mt-1">{prediction.winner}</h2>
                 </div>
             </div>
             <div className={`px-3 py-1 rounded-full border ${confidenceStyle.border} bg-black/30 backdrop-blur`}>
                 <span className={`text-sm font-bold ${confidenceStyle.text}`}>
                    {prediction.confidence} ({confidencePercentage}%)
                 </span>
             </div>
          </div>
          <p className="text-slate-200 text-sm leading-relaxed border-t border-white/10 pt-3 mt-2">
            {prediction.analysis}
          </p>
       </div>

       {/* Sharp Report / Edge Analysis */}
       {prediction.oddsDetails && (
         <div className="bg-[#0d1117] rounded-xl border border-gray-800 p-4">
             <div className="flex items-center justify-between mb-3">
                 <h3 className="text-sm font-bold text-slate-400 uppercase flex items-center gap-2">
                    <svg className="w-4 h-4 text-emerald-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 7h8m0 0v8m0-8l-8 8-4-4-6 6" /></svg>
                    Sharp Report
                 </h3>
                 {prediction.ev && (
                     <span className={`text-xs font-bold px-2 py-0.5 rounded border ${prediction.ev > 0 ? 'bg-emerald-900/30 text-emerald-400 border-emerald-500/30' : 'bg-zinc-800 text-zinc-400 border-zinc-700'}`}>
                         {prediction.ev > 0 ? '+' : ''}{prediction.ev}% EV
                     </span>
                 )}
             </div>

             <div className="grid grid-cols-2 md:grid-cols-3 gap-3 mb-4">
                {/* Kelly Criterion */}
                <div className="bg-zinc-900/50 p-3 rounded-lg border border-zinc-800 flex flex-col items-center justify-center">
                    <span className="text-[10px] uppercase text-slate-500 mb-1">Kelly Stake</span>
                    <span className="text-lg font-black text-white">{prediction.kellyRecommendation || '1.0u'}</span>
                </div>
                {/* Public Consensus */}
                <div className="bg-zinc-900/50 p-3 rounded-lg border border-zinc-800 flex flex-col items-center justify-center relative overflow-hidden">
                    <span className="text-[10px] uppercase text-slate-500 mb-1 z-10">Public Money</span>
                    <span className="text-sm font-bold text-white z-10 text-center">{prediction.oddsDetails.publicConsensus || 'N/A'}</span>
                    <div className="absolute bottom-0 left-0 h-1 bg-blue-500 w-full opacity-20"></div>
                </div>
                {/* Sharp Action */}
                <div className="bg-zinc-900/50 p-3 rounded-lg border border-zinc-800 flex flex-col items-center justify-center relative overflow-hidden">
                    <span className="text-[10px] uppercase text-slate-500 mb-1 z-10">Sharp Action</span>
                    <span className="text-sm font-bold text-amber-400 z-10 text-center">{prediction.oddsDetails.sharpConsensus || 'Unknown'}</span>
                    <div className="absolute bottom-0 left-0 h-1 bg-amber-500 w-full opacity-20"></div>
                </div>
             </div>

             {/* Bookmaker Comparison Table */}
             <div className="overflow-hidden rounded-lg border border-zinc-800">
                 <table className="w-full text-xs text-left">
                    <thead className="bg-zinc-800 text-slate-400">
                        <tr>
                            <th className="p-2">Bookmaker</th>
                            <th className="p-2 text-right">Odds</th>
                            <th className="p-2 text-center">Value</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-zinc-800">
                        {prediction.oddsDetails.bookmakers?.map((book, i) => (
                            <tr key={i} className="hover:bg-zinc-800/50">
                                <td className="p-2 text-slate-300 font-medium">{book.book}</td>
                                <td className="p-2 text-right font-mono text-amber-200">{formatOdds(book.odds)}</td>
                                <td className="p-2 text-center">
                                    <span className={`px-1.5 py-0.5 rounded text-[10px] font-bold ${
                                        book.value === 'Best' ? 'bg-emerald-900 text-emerald-400 border border-emerald-800' : 'text-slate-500'
                                    }`}>
                                        {book.value}
                                    </span>
                                </td>
                            </tr>
                        ))}
                    </tbody>
                 </table>
             </div>
         </div>
       )}

       {/* Matchup History */}
       {prediction.matchupHistory && prediction.matchupHistory.length > 0 && (
         <div className="bg-[#0d1117] rounded-xl border border-gray-800 p-4">
             <h3 className="text-sm font-bold text-slate-400 uppercase mb-3 flex items-center gap-2">
                Head-to-Head History
             </h3>
             <div className="overflow-hidden rounded-lg border border-zinc-800">
                 <table className="w-full text-xs text-left">
                    <thead className="bg-zinc-800 text-slate-400">
                        <tr>
                            <th className="p-2">Date</th>
                            <th className="p-2">Matchup</th>
                            <th className="p-2 text-right">Score</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-zinc-800">
                        {prediction.matchupHistory.map((game, i) => (
                            <tr key={i} className="hover:bg-zinc-800/50">
                                <td className="p-2 text-slate-300">{game.date}</td>
                                <td className="p-2 text-slate-300">
                                  <span className={game.winner === game.homeTeam ? 'text-green-400 font-bold' : ''}>{game.homeTeam}</span>
                                  <span className="text-slate-500 mx-1">vs</span>
                                  <span className={game.winner === game.awayTeam ? 'text-green-400 font-bold' : ''}>{game.awayTeam}</span>
                                </td>
                                <td className="p-2 text-right font-mono text-amber-200">
                                    {game.homeScore}-{game.awayScore}
                                </td>
                            </tr>
                        ))}
                    </tbody>
                 </table>
             </div>
         </div>
       )}

       {/* Key Injuries Section */}
       {prediction.injuries && prediction.injuries.length > 0 && (
            <div className="bg-[#0d1117] rounded-xl border border-gray-800 p-4">
                <h3 className="text-sm font-bold text-slate-400 uppercase mb-3 flex items-center gap-2">
                    <svg className="w-4 h-4 text-rose-500" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" />
                    </svg>
                    Key Injuries
                </h3>
                <div className="grid gap-2">
                    {prediction.injuries.map((injuryStr, idx) => {
                        const { player, status, reason } = parseInjury(injuryStr);
                        const statusStyle = getStatusColor(status);

                        return (
                            <div key={idx} className="flex items-center justify-between bg-zinc-900/50 p-3 rounded-lg border border-zinc-800/50 hover:bg-zinc-800 transition-colors">
                                <div className="flex flex-col min-w-0 mr-2">
                                    <span className="font-bold text-slate-200 text-sm truncate">{player}</span>
                                    {reason && <span className="text-xs text-slate-500 truncate">{reason}</span>}
                                </div>
                                <span className={`flex-shrink-0 text-[10px] font-bold px-2 py-1 rounded border uppercase tracking-wider ${statusStyle}`}>
                                    {status}
                                </span>
                            </div>
                        );
                    })}
                </div>
            </div>
       )}

       {/* Prop Bets Section */}
       {prediction.props && prediction.props.length > 0 && (
         <div className="space-y-3">
             <div className="flex flex-col md:flex-row md:items-center justify-between gap-3">
                 <h3 className="text-sm font-bold text-slate-400 uppercase flex items-center gap-2">
                    <AnalyticsIcon className="w-4 h-4" />
                    Top +EV Props
                 </h3>
                 <div className="flex gap-2">
                    <div className="relative flex-grow md:flex-grow-0">
                        <SearchIcon className="w-4 h-4 absolute left-2 top-1/2 transform -translate-y-1/2 text-slate-500" />
                        <input 
                            type="text" 
                            placeholder="Search player..." 
                            value={searchQuery}
                            onChange={(e) => setSearchQuery(e.target.value)}
                            className="w-full md:w-40 bg-zinc-800 border-none text-xs text-white rounded pl-8 pr-2 py-1.5 focus:ring-1 focus:ring-purple-500"
                        />
                    </div>
                    <div className="flex bg-zinc-800 rounded p-0.5">
                        <button onClick={() => setTypeFilter('All')} className={`text-[10px] px-2 py-1 rounded transition-all ${typeFilter === 'All' ? 'bg-purple-600 text-white shadow-sm' : 'text-slate-400 hover:text-white'}`}>All</button>
                        <button onClick={() => setTypeFilter('MORE')} className={`text-[10px] px-2 py-1 rounded transition-all ${typeFilter === 'MORE' ? 'bg-green-600 text-white shadow-sm' : 'text-slate-400 hover:text-white'}`}>More</button>
                        <button onClick={() => setTypeFilter('LESS')} className={`text-[10px] px-2 py-1 rounded transition-all ${typeFilter === 'LESS' ? 'bg-rose-600 text-white shadow-sm' : 'text-slate-400 hover:text-white'}`}>Less</button>
                    </div>
                 </div>
             </div>

            <div className="grid gap-3">
                {filteredProps.map((prop, index) => {
                    const isInSlip = pickSlip.some(p => p.player === prop.player && p.stat === prop.stat && p.line === prop.line);
                    const isMore = prop.type === 'MORE';

                    return (
                        <div 
                            key={index} 
                            className={`relative bg-[#0d1117] rounded-xl border p-4 flex items-center justify-between group transition-all duration-300 ${
                                prop.isBestValue 
                                    ? 'border-amber-500/60 shadow-[0_0_15px_rgba(245,158,11,0.15)] bg-gradient-to-br from-[#1a0e05] to-[#0d1117]' 
                                    : 'border-gray-800 hover:border-purple-500/50 hover:bg-[#161b22]'
                            }`}
                        >
                            {/* Best Value Badge */}
                            {prop.isBestValue && (
                                <div className="absolute -top-3 -right-2 md:right-auto md:left-4 z-10 flex items-center gap-1 bg-amber-500 text-black text-[10px] font-black px-2 py-1 rounded-full shadow-lg border-2 border-[#0d1117] animate-pulse-slow">
                                    <DoubleCheckIcon className="w-3 h-3" />
                                    AI CHOICE
                                </div>
                            )}

                            <div className="flex items-center gap-4 flex-1 min-w-0 mr-4">
                                <img 
                                    src={`https://i.pravatar.cc/150?u=${encodeURIComponent(prop.player)}`} 
                                    alt={prop.player} 
                                    className={`w-14 h-14 rounded-full border-2 shadow-md flex-shrink-0 object-cover ${prop.isBestValue ? 'border-amber-500' : 'border-gray-700'}`}
                                />
                                <div className="flex-1 min-w-0">
                                    <div className="flex items-center gap-2 mb-1">
                                        <span className={`font-bold truncate text-sm md:text-base ${prop.isBestValue ? 'text-amber-100' : 'text-white'}`}>{prop.player}</span>
