                        >
                            <SendIcon className="w-4 h-4" />
                            Analyze {searchQuery} with AI
                        </button>
                    </div>
                )}
            </div>
         </div>
       )}

       {/* Sources Footnote */}
        {prediction.sources && prediction.sources.length > 0 && (
            <div className="mt-4 pt-4 border-t border-gray-800">
                 <p className="text-[10px] uppercase tracking-wider text-slate-600 mb-2 font-bold">Live Data Sources:</p>
                 <div className="flex flex-wrap gap-2">
                    {prediction.sources.map((source, idx) => (
                        source.web?.uri && (
                            <a 
                                key={idx} 
                                href={source.web.uri} 
                                target="_blank" 
                                rel="noopener noreferrer"
                                className="text-[10px] bg-zinc-900 border border-zinc-800 text-blue-400 px-2 py-1 rounded hover:bg-zinc-800 hover:border-blue-900 transition-colors truncate max-w-[200px]"
                            >
                                {source.web.title || new URL(source.web.uri).hostname}
                            </a>
