    </div>
  );
});

import { GoogleGenAI, Type } from "@google/genai";
import type { Game } from "../types";

export const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

// Define the JSON schema for the prediction response to ensure structured output from the model.
export const predictionSchema = {
  type: Type.OBJECT,
  properties: {
    winner: { 
      type: Type.STRING,
      description: "The predicted winning team."
    },
    loser: {
      type: Type.STRING,
      description: "The predicted losing team."
    },
    confidence: {
      type: Type.STRING,
      description: "Confidence level of the prediction (High, Medium, or Low).",
      enum: ["High", "Medium", "Low"]
    },
    confidenceScore: {
      type: Type.NUMBER,
      description: "A numerical confidence score between 0 and 1 (e.g., 0.85 for 85%)."
    },
    ev: {
      type: Type.NUMBER,
      description: "Calculated +EV (Expected Value) percentage based on sharp bookmaker lines (e.g. 5.2 for 5.2%)."
    },
    kellyRecommendation: {
      type: Type.STRING,
      description: "Suggested bet size using Kelly Criterion (e.g. '1.2 Units' or '0.5 Units')."
    },
    analysis: {
      type: Type.STRING,
      description: "A sharp, deep-dive analysis (3-4 sentences) including WEATHER impact, REFEREE trends, and Defense vs Position (DvP) context."
    },
    injuries: {
      type: Type.ARRAY,
      description: "List of key injuries/absences formatted as 'Player Name (Status) - Reason'.",
      items: { type: Type.STRING }
    },
    trends: {
      type: Type.ARRAY,
      description: "List of 3-5 crucial betting trends (ATS, Over/Under, H2H) that support the prediction.",
