                type: { type: Type.STRING, enum: ["MORE", "LESS"], description: "Predicting MORE (Over) or LESS (Under)?" },
                odds: { type: Type.STRING, description: "Implied odds e.g. -110" },
                probability: { type: Type.STRING, description: "e.g. 58%" },
                ev: { type: Type.NUMBER, description: "Expected Value % for this specific prop." },
                analysis: { type: Type.STRING, description: "Brief reasoning, e.g. 'Hit in 4/5 last games'" },
                isBestValue: { type: Type.BOOLEAN, description: "Set to TRUE for the SINGLE best prop in the list (highest EV)." },
                homeAvg: { type: Type.STRING, description: "Average stat at Home (e.g. '24.2')" },
                awayAvg: { type: Type.STRING, description: "Average stat on the Road (e.g. '18.5')" }
            },
            required: ["player", "bet", "line", "stat", "type", "odds", "probability", "analysis"]
        }
    }
  },
  required: ["winner", "loser", "confidence", "confidenceScore", "analysis", "gameScript", "statComparison", "injuries", "odds", "oddsDetails", "props", "trends"]
};

export const getSchedule = async (sport: string): Promise<Game[]> => {
  const sportQuery = sport === 'NFL' ? 'NFL Football' : sport;

  // OPTIMIZED PROMPT: Short, direct instructions to reduce latency and token usage.
  // Explicitly requests "Live" details (Quarter, Period) to satisfy the "3rd quarter" requirement.
  const prompt = `
    Fetch ${sportQuery} schedule & live scores for TODAY (${new Date().toLocaleDateString()}).
    CRITICAL: For LIVE games, extract the exact Period/Quarter (e.g. "Q1", "Q3", "Halftime").
    Include upcoming games for the next 24 hours.

    Return STRICT JSON ONLY. No markdown.
    Format:
    {
      "games": [
        {
          "id": "Home-Away-Date",
          "homeTeam": "Name",
          "awayTeam": "Name",
          "time": "Live Q3 5:12" or "7:00 PM EST",
          "date": "Today" or "Oct 25",
          "status": "Live" | "Scheduled" | "Finished",
          "score": "24-17",
          "odds": { "spread": "-5.5", "total": "48.5", "moneyline": "-150" }
        }
      ]
    }

    Sort order: Live games first, then by start time.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        temperature: 0.0, // Reduced temperature for faster, deterministic output
      }
    });

    const text = response.text || '';
    const jsonString = text.replace(/^```json\s*/, '').replace(/```$/, '').trim();

    try {
        const data = JSON.parse(jsonString);
        return data.games || [];
    } catch (parseError) {
        // Fallback: simple text extraction or return empty if JSON fails (fail fast)
        console.warn("JSON parse failed, returning empty to avoid crash", parseError);
        return [];
    }
  } catch (error) {
    console.error("Failed to fetch schedule:", error);
    return [];
  }
};

import React, { useState, useCallback, useEffect, useRef } from 'react';
import { Header } from './components/Header';
import { SportSelector } from './components/SportSelector';
import { GameSchedule } from './components/GameSchedule';
import { PredictionDisplay } from './components/PredictionDisplay';
import { Loader } from './components/Loader';
import { Footer } from './components/Footer';
import { SettingsModal } from './components/SettingsModal';
import { TokenomicsModal } from './components/TokenomicsModal';
import { ChatInterface } from './components/ChatInterface';
import { SuggestionChips } from './components/SuggestionChips';
import { PickSlip } from './components/PickSlip';
import { ai, predictionSchema } from './services/geminiService';
import type { Prediction, UserSettings, ChatMessage, Game, PropBet, ConfidenceLevel } from './types';
import type { Chat } from '@google/genai';

const App: React.FC = () => {
  const [settings, setSettings] = useState<UserSettings>(() => {
    try {
      const storedSettings = localStorage.getItem('prognosSettings');
      if (storedSettings) {
        return JSON.parse(storedSettings);
      }
    } catch (error) {
      console.error("Failed to parse settings from localStorage", error);
    }
    return {
      preferredSport: 'NFL',
      defaultConfidenceFilter: 'All',
      oddsFormat: 'American',
    };
  });

  const [selectedSport, setSelectedSport] = useState<string>(settings.preferredSport);
  const [selectedGame, setSelectedGame] = useState<Game | null>(null);

  const [prediction, setPrediction] = useState<Prediction | null>(null);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [isReplying, setIsReplying] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const [isSettingsOpen, setIsSettingsOpen] = useState<boolean>(false);
  const [isTokenModalOpen, setIsTokenModalOpen] = useState<boolean>(false);

  const [chat, setChat] = useState<Chat | null>(null);
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [showSuggestions, setShowSuggestions] = useState<boolean>(false);
  const chatRef = useRef<HTMLDivElement>(null);

  // Pick Slip State
  const [pickSlip, setPickSlip] = useState<PropBet[]>([]);

  useEffect(() => {
    setSelectedSport(settings.preferredSport);
  }, [settings.preferredSport]);

  // Reset selected game when sport changes
  useEffect(() => {
    setSelectedGame(null);
    setPrediction(null);
    setMessages([]);
    setChat(null);
  }, [selectedSport]);

  useEffect(() => {
    if (chatRef.current) {
        chatRef.current.scrollTop = chatRef.current.scrollHeight;
    }
  }, [messages]);

  const handleOpenSettings = useCallback(() => {
    setIsSettingsOpen(true);
  }, []);

  const handleCloseSettings = useCallback(() => {
    setIsSettingsOpen(false);
  }, []);

  const handleOpenToken = useCallback(() => {
    setIsTokenModalOpen(true);
  }, []);

  const handleCloseToken = useCallback(() => {
    setIsTokenModalOpen(false);
  }, []);

  const handleSaveSettings = useCallback((newSettings: UserSettings) => {
    setSettings(newSettings);
    try {
        localStorage.setItem('prognosSettings', JSON.stringify(newSettings));
    } catch (error) {
        console.error("Failed to save settings to localStorage", error);
    }
    setIsSettingsOpen(false);
  }, []);

  const handleTogglePick = useCallback((prop: PropBet) => {
    setPickSlip(prev => {
        const exists = prev.some(p => p.player === prop.player && p.stat === prop.stat && p.line === prop.line);
        if (exists) {
            return prev.filter(p => !(p.player === prop.player && p.stat === prop.stat && p.line === prop.line));
        } else {
            if (prev.length >= 5) {
                // Optionally show a toast/alert here
                return prev;
            }
            return [...prev, prop];
        }
    });
  }, []);

  const handleRemoveFromSlip = useCallback((prop: PropBet) => {
    setPickSlip(prev => prev.filter(p => !(p.player === prop.player && p.stat === prop.stat && p.line === prop.line)));
  }, []);

  const handlePredict = useCallback(async () => {
    if (!selectedGame) {
      setError('Please select a game from the schedule.');
      return;
    }
    setIsLoading(true);
    setError(null);
    setPrediction(null);
    setMessages([]);
    setChat(null);
    setShowSuggestions(false);

    const gameContext = selectedGame.status === 'Live' 
        ? `LIVE (${selectedGame.score}, ${selectedGame.time})`
        : `Scheduled: ${selectedGame.date} ${selectedGame.time}`;

    // OPTIMIZED PROMPT: Requesting Deep Data & Analytics (OddsJam/Action Network style)
    const prompt = `
      Analyze ${selectedGame.league} Match: "${selectedGame.homeTeam}" vs "${selectedGame.awayTeam}" (${gameContext}).

      ACT AS A SHARP BETTOR & DATA SCIENTIST. USE ALL AVAILABLE ANALYTICS:

      CRITICAL ROSTER OVERRIDE: Luka Doncic is now playing for the Los Angeles Lakers. Factor this major change into all chemistry, lineup analysis, and prop predictions if the Lakers are playing.

      1. **Matchup DNA**: Identify the 3 most critical advanced stats for this specific game (e.g. "Effective FG%", "Pace", "Red Zone Efficiency") and compare the teams.
      2. **Game Script**: Simulate the flow of the game. Will it be a blowout? A defensive grind? A 4th quarter comeback?
      3. **Win Probability**: Calculate exact win % based on DVOA, EPA, and Pythagorean expectation.
      4. **Money Flow**: Identify "Sharp Money" (High Volume/Low Ticket %) vs "Public Money".
      5. **Arbitrage/Edge**: Find discrepancies between Pinnacle (Sharp) and DraftKings/FanDuel (Public).

      FETCH DATA & RETURN JSON:
      1. **Winner**: Prediction with high confidence logic.
      2. **Game Script**: A narrative description of how the game will play out.
      3. **Stat Comparison**: Top 3 defining advanced metrics for this matchup.
      4. **Trends**: List 4 specific, high-impact betting trends.
      5. **Player Props (Top 5)**:
         - Find MISPRICED lines based on Defense vs Position (DvP).
         - **CRITICAL**: Include Home/Away split data (e.g. "24.5 @ Home" vs "18.2 @ Road") in 'homeAvg' and 'awayAvg' fields.
         - **IMPORTANT**: Set 'isBestValue': true for the ONE single best prop bet.

      Output STRICT JSON matching schema.
    `;

    try {
      const newChat = ai.chats.create({ 
        model: 'gemini-2.5-flash',
        config: {
          systemInstruction: `You are Pro N os, an elite sports handicapper using advanced data science.
          - Prioritize "+EV" (Expected Value) and "CLV" (Closing Line Value).
          - Use data-driven language: "Standard Deviation", "Implied Probability", "Market Efficiency".
          - Be concise but extremely insightful. Return JSON only.`,
          responseSchema: predictionSchema,
          responseMimeType: 'application/json',
        }
      });

      setChat(newChat);

      const response = await newChat.sendMessage({ message: prompt });
      const text = response.text || '';

      try {
        const parsedPrediction = JSON.parse(text) as Prediction;
        setPrediction(parsedPrediction);
        setMessages([{ role: 'model', content: parsedPrediction }]);
        setShowSuggestions(true);
      } catch (parseError) {
        console.error("JSON Parse Error:", parseError, text);
        setError('Failed to parse prediction data. The AI returned an unexpected response format.');
      }
    } catch (err) {
      console.error("Prediction Error:", err);
      setError('An error occurred while generating the prediction. Please try again.');
    } finally {
      setIsLoading(false);
    }
  }, [selectedGame]);

  const handleSendMessage = useCallback(async (text: string) => {
    if (!chat) return;

    const userMsg: ChatMessage = { role: 'user', content: text };
    setMessages(prev => [...prev, userMsg]);
    setIsReplying(true);
    setShowSuggestions(false);

    try {
        const response = await chat.sendMessage({ message: text });
        const responseText = response.text || "I couldn't generate a response.";

        const modelMsg: ChatMessage = { role: 'model', content: responseText };
        setMessages(prev => [...prev, modelMsg]);
    } catch (error) {
        console.error("Chat Error:", error);
        setMessages(prev => [...prev, { role: 'model', content: "Sorry, I encountered an error answering that." }]);
    } finally {
        setIsReplying(false);
    }
  }, [chat]);

  const handleAnalyzePickSlip = useCallback(async () => {
    if (pickSlip.length < 2) return;

    setIsLoading(true);
    setPrediction(null);
    setMessages([]);
    setChat(null); 

    const prompt = `
        Analyze this Pick Slip for Correlation & Risk (OddsJam Style):
        ${pickSlip.map(p => `- ${p.player} ${p.type} ${p.line} ${p.stat} (${p.odds})`).join('\n')}

        Provide:
        1. **Correlation Analysis**: Do these picks conflict or support each other?
        2. **Risk Rating**: Low/Medium/High risk.
        3. **Combined EV%**: Estimate the total expected value.
        4. **Recommendation**: "Play It" or "Adjust".
    `;

    try {
        const newChat = ai.chats.create({ 
            model: 'gemini-2.5-flash',
            config: {
                systemInstruction: "You are a risk management expert. Analyze pick slips for correlation, EV, and hedging opportunities."
            }
        });
        setChat(newChat);

        const response = await newChat.sendMessage({ message: prompt });
        const text = response.text || '';

        setMessages([
            { role: 'user', content: "Analyze my Pick Slip" },
            { role: 'model', content: text }
        ]);
        setIsLoading(false);
    } catch (err) {
        console.error(err);
        setIsLoading(false);
        setError("Failed to analyze slip.");
    }
  }, [pickSlip]);

  return (
    <div className="min-h-screen bg-black text-white font-sans selection:bg-purple-500/30">
      <Header onOpenSettings={handleOpenSettings} onOpenToken={handleOpenToken} />

      <main className="container mx-auto px-4 py-6 max-w-4xl relative z-0">

        {/* Error Banner */}
        {error && (
            <div className="bg-red-900/50 border border-red-500/50 text-red-200 px-4 py-3 rounded-xl mb-6 flex items-center justify-between animate-fade-in">
                <span>{error}</span>
                <button onClick={() => setError(null)} className="text-red-400 hover:text-white">&times;</button>
            </div>
        )}

        {/* Main Content Area */}
        {!prediction && messages.length === 0 && !isLoading ? (
            <div className="space-y-8 animate-fade-in">
                <SportSelector 
                    selectedSport={selectedSport} 
                    onSelectSport={setSelectedSport} 
                />

                <GameSchedule 
                    sport={selectedSport}
                    selectedGame={selectedGame}
                    onSelectGame={(game) => {
                        setSelectedGame(game);
                        setError(null);
                    }}
                />

                {selectedGame && (
                    <div className="fixed bottom-6 left-0 right-0 p-4 flex justify-center z-20 pointer-events-none">
                         <button
                            onClick={handlePredict}
                            className="pointer-events-auto bg-gradient-to-r from-amber-500 to-orange-600 hover:from-amber-400 hover:to-orange-500 text-black font-black text-lg py-4 px-12 rounded-full shadow-[0_0_30px_rgba(245,158,11,0.4)] hover:shadow-[0_0_50px_rgba(245,158,11,0.6)] transform hover:scale-105 transition-all duration-300 flex items-center gap-2"
                        >
                            <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
                            GENERATE PREDICTION
                        </button>
                    </div>
                )}
            </div>
        ) : isLoading ? (
            <Loader />
        ) : (
            <div className="space-y-4 animate-fade-in">
                 <button 
                    onClick={() => {
                        setPrediction(null);
                        setMessages([]);
                        setChat(null);
                    }}
                    className="flex items-center gap-2 text-stone-400 hover:text-white mb-2 transition-colors"
                 >
                    <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7m0 0l7-7m-7 7h18" /></svg>
                    Back to Schedule
                 </button>

                 <ChatInterface 
                    messages={messages}
                    isReplying={isReplying}
                    onSendMessage={handleSendMessage}
                    oddsFormat={settings.oddsFormat}
                    onAnalyzeProp={(prop) => handleSendMessage(`Deep dive analysis for ${prop.player} ${prop.bet}`)}
                    pickSlip={pickSlip}
                    onTogglePick={handleTogglePick}
                    onSearchPlayer={(player) => handleSendMessage(`Generate a comprehensive prop bet analysis for ${player} in this specific matchup. Include stats, trends, and a recommended line if valuable.`)}
                 />

                 {showSuggestions && prediction && (
                    <SuggestionChips 
                        prediction={prediction} 
                        onSelect={handleSendMessage} 
                    />
                 )}
            </div>
        )}
      </main>

      <PickSlip 
        picks={pickSlip} 
        onRemove={handleRemoveFromSlip}
        onAnalyze={handleAnalyzePickSlip}
      />

      <Footer />

      <SettingsModal 
        isOpen={isSettingsOpen} 
        onClose={handleCloseSettings} 
        currentSettings={settings}
        onSave={handleSaveSettings}
      />

      <TokenomicsModal 
        isOpen={isTokenModalOpen}
        onClose={handleCloseToken}
      />
    </div>
  );
};

