                                        </div>
                                        <span className={`text-[10px] font-bold ${isHighCertainty ? 'text-amber-400' : 'text-purple-400'}`}>{prop.probability} Probability</span>
                                    </div>
                                </div>
                            </div>

                            <div className="flex flex-col gap-2">
                                <button 
                                    onClick={() => onTogglePick && onTogglePick(prop)}
                                    className={`w-10 h-10 rounded-lg flex items-center justify-center transition-colors ${
