                                >
                                    {isInSlip ? <CheckIcon className="w-5 h-5" /> : <PlusIcon className="w-5 h-5" />}
                                </button>
                                <button 
                                    onClick={() => onAnalyzeProp && onAnalyzeProp(prop)}
                                    className="w-10 h-10 rounded-lg bg-zinc-800 text-slate-400 hover:text-blue-400 border border-zinc-700 flex items-center justify-center"
                                >
                                    <SearchIcon className="w-5 h-5" />
                                </button>
                            </div>
                        </div>
                    );
                })}
            </div>
         </div>
       )}

       {/* Custom Edge Analyzer Form */}
       <div className="bg-gradient-to-br from-[#161b22] to-black rounded-xl border border-gray-800 p-5 mt-4">
           <h3 className="text-sm font-bold text-amber-500 uppercase mb-4 flex items-center gap-2">
              <AnalyticsIcon className="w-4 h-4" />
              Manual Custom Edge Request
           </h3>
           <form onSubmit={handleCustomAnalyze} className="flex flex-col md:flex-row gap-3">
               <input 
                  type="text" 
                  placeholder="Player (e.g. LeBron James)"
                  value={customPlayer}
                  onChange={(e) => setCustomPlayer(e.target.value)}
                  className="flex-1 bg-black border border-zinc-800 rounded-lg px-4 py-2 text-sm focus:ring-1 focus:ring-amber-500 focus:outline-none"
               />
               <input 
                  type="text" 
                  placeholder="Prop (e.g. Over 24.5 Points)"
                  value={customLine}
                  onChange={(e) => setCustomLine(e.target.value)}
                  className="flex-1 bg-black border border-zinc-800 rounded-lg px-4 py-2 text-sm focus:ring-1 focus:ring-amber-500 focus:outline-none"
               />
               <button 
                  type="submit"
                  disabled={!customPlayer || !customLine}
                  className="bg-amber-600 hover:bg-amber-500 disabled:opacity-50 text-black font-bold px-6 py-2 rounded-lg transition-all flex items-center gap-2 justify-center"
               >
                  <SendIcon className="w-4 h-4" />
                  ANALYZE EDGE
               </button>
           </form>
           <p className="text-[10px] text-slate-500 mt-2 italic">Ask AI to perform a targeted math-check on any specific bet you have in mind.</p>
       </div>
    </div>
  );
});

import React, { useState, useCallback, useEffect, useRef } from 'react';
import { Header } from './components/Header';
import { SportSelector } from './components/SportSelector';
import { GameSchedule } from './components/GameSchedule';
import { PredictionDisplay } from './components/PredictionDisplay';
import { Loader } from './components/Loader';
import { Footer } from './components/Footer';
import { SettingsModal } from './components/SettingsModal';
import { TokenomicsModal } from './components/TokenomicsModal';
import { ChatInterface } from './components/ChatInterface';
import { SuggestionChips } from './components/SuggestionChips';
import { PickSlip } from './components/PickSlip';
import { ai, predictionSchema } from './services/geminiService';
import type { Prediction, UserSettings, ChatMessage, Game, PropBet, ConfidenceLevel } from './types';
import type { Chat } from '@google/genai';

const App: React.FC = () => {
  const [settings, setSettings] = useState<UserSettings>(() => {
    try {
      const storedSettings = localStorage.getItem('prognosSettings');
      if (storedSettings) {
        return JSON.parse(storedSettings);
      }
    } catch (error) {
      console.error("Failed to parse settings from localStorage", error);
    }
    return {
      preferredSport: 'NFL',
      defaultConfidenceFilter: 'All',
      oddsFormat: 'American',
    };
  });

  const [selectedSport, setSelectedSport] = useState<string>(settings.preferredSport);
  const [selectedGame, setSelectedGame] = useState<Game | null>(null);

  const [prediction, setPrediction] = useState<Prediction | null>(null);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [isReplying, setIsReplying] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const [isSettingsOpen, setIsSettingsOpen] = useState<boolean>(false);
  const [isTokenModalOpen, setIsTokenModalOpen] = useState<boolean>(false);

  const [chat, setChat] = useState<Chat | null>(null);
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [showSuggestions, setShowSuggestions] = useState<boolean>(false);
  const chatRef = useRef<HTMLDivElement>(null);

  // Pick Slip State
  const [pickSlip, setPickSlip] = useState<PropBet[]>([]);

  useEffect(() => {
    setSelectedSport(settings.preferredSport);
  }, [settings.preferredSport]);

  // Reset selected game when sport changes
  useEffect(() => {
    setSelectedGame(null);
    setPrediction(null);
    setMessages([]);
    setChat(null);
  }, [selectedSport]);

  useEffect(() => {
    if (chatRef.current) {
        chatRef.current.scrollTop = chatRef.current.scrollHeight;
    }
  }, [messages]);

  const handleOpenSettings = useCallback(() => {
    setIsSettingsOpen(true);
  }, []);

  const handleCloseSettings = useCallback(() => {
    setIsSettingsOpen(false);
  }, []);

  const handleOpenToken = useCallback(() => {
    setIsTokenModalOpen(true);
  }, []);

  const handleCloseToken = useCallback(() => {
    setIsTokenModalOpen(false);
  }, []);

  const handleSaveSettings = useCallback((newSettings: UserSettings) => {
    setSettings(newSettings);
    try {
        localStorage.setItem('prognosSettings', JSON.stringify(newSettings));
    } catch (error) {
        console.error("Failed to save settings to localStorage", error);
    }
    setIsSettingsOpen(false);
  }, []);

  const handleTogglePick = useCallback((prop: PropBet) => {
    setPickSlip(prev => {
        const exists = prev.some(p => p.player === prop.player && p.stat === prop.stat && p.line === prop.line);
        if (exists) {
            return prev.filter(p => !(p.player === prop.player && p.stat === prop.stat && p.line === prop.line));
        } else {
            if (prev.length >= 5) {
                return prev;
            }
            return [...prev, prop];
        }
    });
  }, []);

  const handleRemoveFromSlip = useCallback((prop: PropBet) => {
    setPickSlip(prev => prev.filter(p => !(p.player === prop.player && p.stat === prop.stat && p.line === prop.line)));
  }, []);

  const handlePredict = useCallback(async () => {
    if (!selectedGame) {
      setError('Please select a game from the schedule.');
      return;
    }
    setIsLoading(true);
    setError(null);
    setPrediction(null);
    setMessages([]);
    setChat(null);
    setShowSuggestions(false);

    const gameContext = selectedGame.status === 'Live' 
        ? `LIVE (${selectedGame.score}, ${selectedGame.time})`
        : `Scheduled: ${selectedGame.date} ${selectedGame.time}`;

    const prompt = `
      Perform an elite-level AI data analysis for ${selectedGame.league}: "${selectedGame.homeTeam}" vs "${selectedGame.awayTeam}" (${gameContext}).

      TARGET GOAL: Identify "Mathematical Profit Locks." 
      Focus on finding EXACTLY 5 player props with the highest edge. 
      If any prop reaches a probability of 65% or higher based on market inefficiency (Steam moves vs Public fade), flag it as a "STRIKE EDGE".

      ROSTER OVERRIDE: Luka Doncic is on the LAKERS. Analyze the 3-headed monster of Luka, LeBron, and AD. 
      Luka's elite passing (10+ AST floor) creates wide-open shots for AD and LeBron. Analyze specifically how Luka's high usage affects his teammates' props.

      ANALYTICS REQUIREMENTS:
      1. **Matchup DNA**: Compare 3 defining advanced metrics (e.g., Offensive Rating, Pace, DvP).
      2. **Game Simulation Script**: A quarter-by-quarter narrative of how the AI simulates the game flowing.
      3. **Win Probability**: Use Sharp Consensus data.
      4. **Top 5 Props**: Selection must be based on +EV (Expected Value). We want to "Profit" by finding the biggest line discrepancies.

      Output STRICT JSON matching schema.
    `;

    try {
      const newChat = ai.chats.create({ 
        model: 'gemini-2.5-flash',
        config: {
          systemInstruction: `You are Pro N os, the world's leading sports analytics AI. 
          - You specialize in identifying props with >65% probability.
          - You ALWAYS factor in the Luka Doncic to Lakers roster update.
          - Your goal is to maximize user PROFIT by identifying line value.
          - Return JSON only.`,
          responseSchema: predictionSchema,
          responseMimeType: 'application/json',
        }
      });

      setChat(newChat);

      const response = await newChat.sendMessage({ message: prompt });
      const text = response.text || '';

      try {
        const parsedPrediction = JSON.parse(text) as Prediction;
        setPrediction(parsedPrediction);
        setMessages([{ role: 'model', content: parsedPrediction }]);
        setShowSuggestions(true);
      } catch (parseError) {
        console.error("JSON Parse Error:", parseError, text);
        setError('Failed to parse prediction data.');
      }
    } catch (err) {
      console.error("Prediction Error:", err);
      setError('An error occurred. Please try again.');
    } finally {
      setIsLoading(false);
    }
  }, [selectedGame]);

  const handleSendMessage = useCallback(async (text: string) => {
    if (!chat) return;

    const userMsg: ChatMessage = { role: 'user', content: text };
    setMessages(prev => [...prev, userMsg]);
    setIsReplying(true);
    setShowSuggestions(false);

    try {
        const response = await chat.sendMessage({ message: text });
        const responseText = response.text || "I couldn't generate a response.";

        const modelMsg: ChatMessage = { role: 'model', content: responseText };
        setMessages(prev => [...prev, modelMsg]);
    } catch (error) {
        console.error("Chat Error:", error);
        setMessages(prev => [...prev, { role: 'model', content: "Sorry, I encountered an error." }]);
    } finally {
        setIsReplying(false);
    }
  }, [chat]);

  const handleAnalyzeCustomProp = useCallback((playerName: string, propLine: string) => {
    const customPrompt = `DEEP DIVE ANALYZE: ${playerName} ${propLine}. 
    Use Home/Away splits, DvP context, and sharp money flow. 
    Does this specific prop have a probability of 65% or higher? 
    Give me a "Profit Confidence Rating".`;
    handleSendMessage(customPrompt);
  }, [handleSendMessage]);

  const handleAnalyzePickSlip = useCallback(async () => {
    if (pickSlip.length < 2) return;

    setIsLoading(true);
    setPrediction(null);
    setMessages([]);
    setChat(null); 

    const prompt = `
        Analyze this Pick Slip for Profit & Correlation:
        ${pickSlip.map(p => `- ${p.player} ${p.type} ${p.line} ${p.stat}`).join('\n')}

        Provide:
        1. **Combined Probability**: Is this parlay/slip > 65% likely to hit?
        2. **Correlation Report**: Do these picks support each other (e.g., QB/WR stack)?
        3. **Risk Profile**.
    `;

    try {
        const newChat = ai.chats.create({ 
            model: 'gemini-2.5-flash',
            config: {
                systemInstruction: "You are a sharp betting consultant. Analyze slip correlation and combined probability."
            }
        });
        setChat(newChat);

        const response = await newChat.sendMessage({ message: prompt });
        const text = response.text || '';

        setMessages([
            { role: 'user', content: "Analyze my Pick Slip" },
            { role: 'model', content: text }
        ]);
        setIsLoading(false);
    } catch (err) {
        console.error(err);
        setIsLoading(false);
        setError("Failed to analyze slip.");
    }
  }, [pickSlip]);

  return (
    <div className="min-h-screen bg-black text-white font-sans selection:bg-amber-500/30">
      <Header onOpenSettings={handleOpenSettings} onOpenToken={handleOpenToken} />

      <main className="container mx-auto px-4 py-6 max-w-4xl relative z-0">

        {error && (
            <div className="bg-red-900/50 border border-red-500/50 text-red-200 px-4 py-3 rounded-xl mb-6 flex items-center justify-between animate-fade-in">
                <span>{error}</span>
                <button onClick={() => setError(null)} className="text-red-400 hover:text-white">&times;</button>
            </div>
        )}

        {!prediction && messages.length === 0 && !isLoading ? (
            <div className="space-y-8 animate-fade-in">
                <SportSelector 
                    selectedSport={selectedSport} 
                    onSelectSport={setSelectedSport} 
                />

                <GameSchedule 
                    sport={selectedSport}
                    selectedGame={selectedGame}
                    onSelectGame={(game) => {
                        setSelectedGame(game);
                        setError(null);
                    }}
                />

                {selectedGame && (
                    <div className="fixed bottom-6 left-0 right-0 p-4 flex justify-center z-20 pointer-events-none">
                         <button
                            onClick={handlePredict}
                            className="pointer-events-auto bg-gradient-to-r from-amber-500 via-orange-500 to-amber-600 text-black font-black text-lg py-4 px-12 rounded-full shadow-[0_0_40px_rgba(245,158,11,0.5)] hover:shadow-[0_0_60px_rgba(245,158,11,0.7)] transform hover:scale-105 transition-all duration-300 flex items-center gap-2 group"
                        >
                            <svg className="w-6 h-6 group-hover:animate-pulse" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
                            GENERATE PROFIT PREDICTION
                        </button>
                    </div>
                )}
            </div>
        ) : isLoading ? (
            <Loader />
        ) : (
            <div className="space-y-4 animate-fade-in">
                 <button 
                    onClick={() => {
                        setPrediction(null);
                        setMessages([]);
                        setChat(null);
                    }}
                    className="flex items-center gap-2 text-stone-400 hover:text-white mb-2 transition-colors"
                 >
                    <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7m0 0l7-7m-7 7h18" /></svg>
                    Back to Schedule
                 </button>

                 <ChatInterface 
                    messages={messages}
                    isReplying={isReplying}
                    onSendMessage={handleSendMessage}
                    oddsFormat={settings.oddsFormat}
                    onAnalyzeProp={(prop) => handleAnalyzeCustomProp(prop.player, prop.bet)}
                    pickSlip={pickSlip}
                    onTogglePick={handleTogglePick}
                    onSearchPlayer={(player) => handleSendMessage(`Analyze ${player}'s highest probability prop for this game. Seek >65% edges.`)}
                 />

                 {showSuggestions && prediction && (
                    <SuggestionChips 
                        prediction={prediction} 
                        onSelect={handleSendMessage} 
                    />
                 )}
            </div>
        )}
      </main>

      <PickSlip 
        picks={pickSlip} 
        onRemove={handleRemoveFromSlip}
        onAnalyze={handleAnalyzePickSlip}
      />

      <Footer />

      <SettingsModal 
        isOpen={isSettingsOpen} 
        onClose={handleCloseSettings} 
        currentSettings={settings}
        onSave={handleSaveSettings}
      />

      <TokenomicsModal 
        isOpen={isTokenModalOpen}
        onClose={handleCloseToken}
      />
    </div>
  );
};

export default App;

import React, { memo, useState, useMemo } from 'react';
import type { Prediction, OddsFormat, PropBet } from '../types';
import { AnalyticsIcon, PlusIcon, CheckIcon, SearchIcon, DoubleCheckIcon, SendIcon } from './Icons';

interface PredictionDisplayProps {
  prediction: Prediction;
  oddsFormat: OddsFormat;
  onAnalyzeProp?: (prop: PropBet) => void;
  pickSlip?: PropBet[];
  onTogglePick?: (prop: PropBet) => void;
  onSearchPlayer?: (player: string) => void;
}

const confidenceStyles: Record<string, { bg: string; text: string; border: string }> = {
    High: { bg: 'bg-green-900/50', text: 'text-green-300', border: 'border-green-800' },
    Medium: { bg: 'bg-amber-900/40', text: 'text-amber-300', border: 'border-amber-700' },
    Low: { bg: 'bg-rose-900/50', text: 'text-rose-300', border: 'border-rose-800' },
};

const convertAmericanToDecimal = (americanOdds: string): string => {
    const odds = parseInt(americanOdds, 10);
    if (isNaN(odds)) return americanOdds;
    let decimalOdds = odds > 0 ? (odds / 100) + 1 : (100 / Math.abs(odds)) + 1;
    return decimalOdds.toFixed(2);
};

export const PredictionDisplay: React.FC<PredictionDisplayProps> = memo(({ prediction, oddsFormat, onAnalyzeProp, pickSlip = [], onTogglePick, onSearchPlayer }) => {
  const [typeFilter, setTypeFilter] = useState<'All' | 'MORE' | 'LESS'>('All');
  const [searchQuery, setSearchQuery] = useState<string>('');

  // Custom manual entry state
  const [customPlayer, setCustomPlayer] = useState('');
  const [customLine, setCustomLine] = useState('');

  const confidenceStyle = confidenceStyles[prediction.confidence] || confidenceStyles['Medium'];
  const confidencePercentage = prediction.confidenceScore != null ? (prediction.confidenceScore * 100).toFixed(0) : 'N/A';

  const filteredProps = useMemo(() => {
    if (!prediction.props) return [];
    return prediction.props.filter(prop => {
        const matchesType = typeFilter === 'All' || prop.type === typeFilter;
        const matchesSearch = (prop.player || '').toLowerCase().includes(searchQuery.toLowerCase()) || 
                              (prop.stat || '').toLowerCase().includes(searchQuery.toLowerCase());
        return matchesType && matchesSearch;
    });
  }, [prediction.props, typeFilter, searchQuery]);

  const formatOdds = (odds: string) => {
      if (!odds) return 'N/A';
      return oddsFormat === 'Decimal' ? convertAmericanToDecimal(odds) : odds;
  };

  const handleCustomAnalyze = (e: React.FormEvent) => {
      e.preventDefault();
      if (customPlayer && customLine && onSearchPlayer) {
          onSearchPlayer(`Analyze ${customPlayer} for ${customLine}. Provide full data analysis and check for >65% edge.`);
          setCustomPlayer('');
          setCustomLine('');
      }
  };

  // Find the highest probability prop for the "Mathematical Strike" section
  const bestProp = useMemo(() => {
    if (!prediction.props || prediction.props.length === 0) return null;
    return [...prediction.props].sort((a, b) => parseInt(b.probability) - parseInt(a.probability))[0];
  }, [prediction.props]);

  return (
    <div className="space-y-6 w-full animate-fade-in">
       {/* High-Impact Matchup Banner */}
       <div className={`p-6 rounded-2xl border-2 ${confidenceStyle.border} ${confidenceStyle.bg} backdrop-blur-md shadow-[0_0_30px_rgba(0,0,0,0.5)] relative overflow-hidden`}>
          <div className="absolute top-0 right-0 w-32 h-32 bg-white/5 rounded-full blur-3xl -translate-y-1/2 translate-x-1/2"></div>

          <div className="flex flex-col md:flex-row justify-between items-center gap-6 relative z-10">
             <div className="flex items-center gap-5">
                 <div className="relative">
                    <img 
                        src={`https://ui-avatars.com/api/?name=${encodeURIComponent(prediction.winner)}&background=f59e0b&color=000&size=128&bold=true`}
