                    <div className="flex items-center gap-2 mt-2">
                         <div className="h-1.5 w-24 bg-zinc-800 rounded-full overflow-hidden">
                            <div className="h-full bg-amber-500" style={{ width: `${confidencePercentage}%` }}></div>
                         </div>
                         <span className="text-xs font-bold text-slate-400">{confidencePercentage}% Win Prob</span>
                    </div>
                 </div>
             </div>

             <div className="flex flex-col items-center md:items-end gap-2">
                 <div className={`px-4 py-2 rounded-xl border-2 ${confidenceStyle.border} bg-black/40 backdrop-blur flex flex-col items-center`}>
                    <span className={`text-xs font-black uppercase tracking-widest ${confidenceStyle.text}`}>Confidence</span>
                    <span className="text-2xl font-black text-white">{prediction.confidence}</span>
                 </div>
                 {prediction.ev != null && (
