  const filteredProps = useMemo(() => {
    if (!prediction.props) return [];
    return prediction.props.filter(prop => {
        const matchesType = typeFilter === 'All' || prop.type === typeFilter;
        const matchesSearch = (prop.player || '').toLowerCase().includes(searchQuery.toLowerCase()) || 
                              (prop.stat || '').toLowerCase().includes(searchQuery.toLowerCase());
        return matchesType && matchesSearch;
    });
  }, [prediction.props, typeFilter, searchQuery]);

  const formatOdds = (odds: string) => {
      if (!odds) return 'N/A';
      return oddsFormat === 'Decimal' ? convertAmericanToDecimal(odds) : odds;
  };

  const handleCustomAnalyze = (e: React.FormEvent) => {
