                    <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest">
                        Market Edge Prop List
                    </h3>
                 </div>

                 {/* MORE/LESS Filters */}
                 <div className="flex items-center gap-1 bg-zinc-900/80 p-1 rounded-xl border border-zinc-800 shadow-lg">
                    <button 
                        onClick={() => setTypeFilter('All')} 
                        className={`px-4 py-1.5 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all ${typeFilter === 'All' ? 'bg-zinc-700 text-white shadow-md' : 'text-slate-500 hover:text-slate-300'}`}
                    >
                        All
                    </button>
                    <button 
                        onClick={() => setTypeFilter('MORE')} 
                        className={`px-4 py-1.5 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all ${typeFilter === 'MORE' ? 'bg-green-600/30 text-green-400 border border-green-500/30' : 'text-slate-500 hover:text-green-500'}`}
                    >
                        More
                    </button>
                    <button 
                        onClick={() => setTypeFilter('LESS')} 
                        className={`px-4 py-1.5 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all ${typeFilter === 'LESS' ? 'bg-rose-600/30 text-rose-400 border border-rose-500/30' : 'text-slate-500 hover:text-rose-500'}`}
                    >
                        Less
                    </button>
                 </div>
            </div>

            <div className="grid gap-4">
                {filteredProps.map((prop, index) => {
                    const isInSlip = pickSlip.some(p => p.player === prop.player && p.stat === prop.stat && p.line === prop.line);
                    const isHighProb = parseInt(prop.probability) >= 65;

                    return (
                        <div 
                            key={index} 
                            className={`group relative bg-[#0d1117] rounded-2xl border p-4 flex flex-col transition-all duration-500 overflow-hidden ${
                                isHighProb 
                                    ? 'border-amber-500/50 bg-gradient-to-br from-[#1a140a] to-[#0d1117] shadow-lg' 
                                    : 'border-zinc-800 hover:border-zinc-700 shadow-md'
                            }`}
                        >
                            <div className="flex items-center justify-between mb-3">
                                <div className="flex items-center gap-4 flex-1 min-w-0">
                                    <div className="relative">
                                        <img src={`https://i.pravatar.cc/150?u=${encodeURIComponent(prop.player)}`} className={`w-14 h-14 rounded-full border-2 object-cover ${isHighProb ? 'border-amber-500' : 'border-zinc-700'}`} />
                                        {isHighProb && <div className="absolute -top-1 -right-1 bg-amber-500 text-[8px] font-black text-black px-1.5 py-0.5 rounded-full border border-black animate-pulse shadow-md">EDGE</div>}
                                    </div>
                                    <div className="flex-1 min-w-0">
                                        <div className="flex items-center gap-2 mb-1">
                                            <span className="font-black text-white truncate text-base">{prop.player}</span>
                                            <span className={`text-[9px] font-black px-1.5 py-0.5 rounded tracking-tighter ${isHighProb ? 'bg-amber-500 text-black' : 'bg-zinc-800 text-slate-500'}`}>{prop.stat}</span>
                                        </div>
                                        <div className="flex items-baseline gap-2">
                                            <span className={`text-xl font-black ${prop.type === 'MORE' ? 'text-green-500' : 'text-rose-500'}`}>{prop.type}</span>
                                            <span className="text-2xl font-black text-white">{prop.line}</span>
                                            <span className="text-xs font-mono text-amber-500/60">{prop.odds}</span>
                                        </div>
                                    </div>
                                </div>
                                <div className="flex gap-2">
                                    <button 
                                        onClick={() => onTogglePick && onTogglePick(prop)}
                                        className={`w-10 h-10 rounded-xl flex items-center justify-center transition-all ${
                                            isInSlip ? 'bg-amber-500 text-black shadow-lg scale-110' : 'bg-zinc-800 text-slate-500 hover:text-white border border-zinc-700'
                                        }`}
                                    >
                                        {isInSlip ? <CheckIcon className="w-5 h-5" /> : <PlusIcon className="w-5 h-5" />}
                                    </button>
                                </div>
                            </div>

                            {/* Multi-Site Comparison */}
                            {prop.lineComparison && prop.lineComparison.length > 0 && (
                                <div className="bg-black/40 rounded-xl p-3 border border-zinc-800/50 mt-1">
                                    <div className="text-[9px] font-black text-slate-500 uppercase tracking-widest mb-2 flex justify-between">
                                        <span>Market Comparison</span>
                                        <span className="text-amber-500">Live Prices</span>
                                    </div>
                                    <div className="flex flex-wrap gap-4">
                                        {prop.lineComparison.map((comp, i) => (
                                            <div key={i} className="flex flex-col">
                                                <span className="text-[10px] text-slate-400 font-bold">{comp.book}</span>
                                                <div className="flex items-center gap-1.5">
                                                    <span className={`text-xs font-black ${comp.line === prop.line ? 'text-white' : 'text-amber-400 underline decoration-amber-500/30'}`}>{comp.line}</span>
                                                    <span className="text-[9px] font-mono text-slate-600">{comp.odds}</span>
                                                </div>
                                            </div>
                                        ))}
                                    </div>
                                </div>
                            )}

                            <div className="mt-3 flex items-center gap-2">
                                <div className="flex-1 h-1 bg-zinc-900 rounded-full overflow-hidden">
                                    <div className={`h-full ${isHighProb ? 'bg-amber-500' : 'bg-zinc-600'}`} style={{ width: prop.probability }}></div>
                                </div>
                                <span className={`text-[9px] font-black ${isHighProb ? 'text-amber-500' : 'text-slate-600'}`}>{prop.probability} HIT RATE</span>
                            </div>
                        </div>
                    );
                })}
            </div>
       </div>

       {/* Target Profit Lab - Manual AI Search */}
       <div className="bg-zinc-900/40 rounded-2xl border-2 border-dashed border-zinc-800 p-6 shadow-xl">
           <div className="flex items-center gap-3 mb-5">
                <div className="p-2.5 bg-amber-500/10 rounded-xl border border-amber-500/30 shadow-inner">
                    <AnalyticsIcon className="w-6 h-6 text-amber-500" />
                </div>
                <div>
                    <h3 className="text-sm font-black text-white uppercase tracking-widest">Mathematical Edge Lab</h3>
                    <p className="text-[10px] text-slate-500 font-bold uppercase tracking-wider">Search Advanced Models & Multi-Site Arbitrage</p>
                </div>
           </div>
           <form onSubmit={handleCustomAnalyze} className="flex flex-col md:flex-row gap-3">
               <input 
                  type="text" 
                  placeholder="Analyze Player (e.g. LeBron)"
                  value={customPlayer}
                  onChange={(e) => setCustomPlayer(e.target.value)}
                  className="flex-1 bg-black border border-zinc-800 rounded-xl px-4 py-3 text-sm font-bold focus:ring-2 focus:ring-amber-500/50 focus:outline-none placeholder-zinc-700 text-white shadow-inner"
               />
               <input 
                  type="text" 
                  placeholder="Prop Goal (e.g. 25+ PTS)"
                  value={customLine}
                  onChange={(e) => setCustomLine(e.target.value)}
                  className="flex-1 bg-black border border-zinc-800 rounded-xl px-4 py-3 text-sm font-bold focus:ring-2 focus:ring-amber-500/50 focus:outline-none placeholder-zinc-700 text-white shadow-inner"
               />
               <button 
                  type="submit"
                  disabled={!customPlayer || !customLine}
                  className="bg-amber-500 hover:bg-amber-400 disabled:opacity-20 text-black font-black px-8 py-3 rounded-xl transition-all shadow-xl shadow-amber-500/10 active:scale-95 group flex items-center gap-2 justify-center"
               >
                  <SearchIcon className="w-4 h-4 group-hover:scale-125 transition-transform" />
