import React, { useState, useCallback, useEffect, useRef } from 'react';
import { Header } from './components/Header';
import { SportSelector } from './components/SportSelector';
import { GameSchedule } from './components/GameSchedule';
import { PredictionDisplay } from './components/PredictionDisplay';
import { Loader } from './components/Loader';
import { Footer } from './components/Footer';
import { SettingsModal } from './components/SettingsModal';
import { TokenomicsModal } from './components/TokenomicsModal';
import { ChatInterface } from './components/ChatInterface';
import { SuggestionChips } from './components/SuggestionChips';
import { PickSlip } from './components/PickSlip';
import { PerformanceSidebar } from './components/PerformanceSidebar';
import { ai, predictionSchema } from './services/geminiService';
import type { Prediction, UserSettings, ChatMessage, Game, PropBet, ConfidenceLevel } from './types';
import type { Chat } from '@google/genai';

const App: React.FC = () => {
  const [settings, setSettings] = useState<UserSettings>(() => {
    try {
      const storedSettings = localStorage.getItem('prognosSettings');
      if (storedSettings) {
        return JSON.parse(storedSettings);
      }
    } catch (error) {
      console.error("Failed to parse settings from localStorage", error);
    }
    return {
      preferredSport: 'NFL',
      defaultConfidenceFilter: 'All',
      oddsFormat: 'American',
    };
  });

  const [selectedSport, setSelectedSport] = useState<string>(settings.preferredSport);
  const [selectedGame, setSelectedGame] = useState<Game | null>(null);

  const [prediction, setPrediction] = useState<Prediction | null>(null);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [isReplying, setIsReplying] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const [isSettingsOpen, setIsSettingsOpen] = useState<boolean>(false);
  const [isTokenModalOpen, setIsTokenModalOpen] = useState<boolean>(false);
  const [isHistorySidebarOpen, setIsHistorySidebarOpen] = useState<boolean>(true);

  const [chat, setChat] = useState<Chat | null>(null);
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [showSuggestions, setShowSuggestions] = useState<boolean>(false);
  const chatRef = useRef<HTMLDivElement>(null);

  // Pick Slip State
  const [pickSlip, setPickSlip] = useState<PropBet[]>([]);

  useEffect(() => {
    setSelectedSport(settings.preferredSport);
  }, [settings.preferredSport]);

  // Reset selected game when sport changes
  useEffect(() => {
    setSelectedGame(null);
    setPrediction(null);
    setMessages([]);
    setChat(null);
  }, [selectedSport]);

  useEffect(() => {
    if (chatRef.current) {
        chatRef.current.scrollTop = chatRef.current.scrollHeight;
    }
  }, [messages]);

  const handleOpenSettings = useCallback(() => {
    setIsSettingsOpen(true);
  }, []);

  const handleCloseSettings = useCallback(() => {
    setIsSettingsOpen(false);
  }, []);

  const handleOpenToken = useCallback(() => {
    setIsTokenModalOpen(true);
  }, []);

  const handleCloseToken = useCallback(() => {
    setIsTokenModalOpen(false);
  }, []);

  const handleSaveSettings = useCallback((newSettings: UserSettings) => {
    setSettings(newSettings);
    try {
        localStorage.setItem('prognosSettings', JSON.stringify(newSettings));
    } catch (error) {
        console.error("Failed to save settings to localStorage", error);
    }
    setIsSettingsOpen(false);
  }, []);

  const handleTogglePick = useCallback((prop: PropBet) => {
    setPickSlip(prev => {
        const exists = prev.some(p => p.player === prop.player && p.stat === prop.stat && p.line === prop.line);
        if (exists) {
            return prev.filter(p => !(p.player === prop.player && p.stat === prop.stat && p.line === prop.line));
        } else {
            if (prev.length >= 5) {
                return prev;
            }
            setIsHistorySidebarOpen(true);
            return [...prev, prop];
        }
    });
  }, []);

  const handleRemoveFromSlip = useCallback((prop: PropBet) => {
    setPickSlip(prev => prev.filter(p => !(p.player === prop.player && p.stat === prop.stat && p.line === prop.line)));
  }, []);

  const handlePredict = useCallback(async () => {
    if (!selectedGame) {
      setError('Please select a game from the schedule.');
      return;
    }
    setIsLoading(true);
    setError(null);
    setPrediction(null);
    setMessages([]);
    setChat(null);
    setShowSuggestions(false);

    const gameContext = selectedGame.status === 'Live' 
        ? `LIVE (${selectedGame.score}, ${selectedGame.time})`
        : `Scheduled: ${selectedGame.date} ${selectedGame.time}`;

    const prompt = `
      PERFORM DEEP AI ANALYSIS for ${selectedGame.league}: "${selectedGame.homeTeam}" vs "${selectedGame.awayTeam}" (${gameContext}).

      CORE MANDATE: 
      1. **Search & Learn**: Use Google Search to find advanced predictive models for this matchup (DVOA, KenPom, ELO). Seek out sharp consensus from Pinnacle/Circa.
      2. **Market Comparison**: Search and compare lines across Betr, PrizePicks, Underdog, and Sleeper for all props.
      3. **History Deep-Dive**: For every player prop, find the ACTUAL results of their LAST 3 GAMES. Mark them as hits/misses based on the current line.
      4. **Luka Roster Update**: Luka Doncic is on the LAKERS. Factor in spacing for AD and LeBron.

      GOAL: Find a "Mathematical Strike" (>65% edge).
      Output STRICT JSON only.
    `;

    try {
      const newChat = ai.chats.create({ 
        model: 'gemini-3-flash-preview',
        config: {
          systemInstruction: `You are Pro N os, a profit-maximizing AI.
          - Prioritize identifying >65% edges.
          - Compare lines between Betr, PrizePicks, Underdog.
          - ALWAYS provide last 3 games performanceHistory for props.
          - Return JSON only.`,
          responseSchema: predictionSchema,
          responseMimeType: 'application/json',
        }
      });

      setChat(newChat);
      const response = await newChat.sendMessage({ message: prompt });
      const text = response.text || '';

      try {
        const parsedPrediction = JSON.parse(text) as Prediction;
        setPrediction(parsedPrediction);
        setMessages([{ role: 'model', content: parsedPrediction }]);
        setShowSuggestions(true);
      } catch (parseError) {
        console.error("JSON Parse Error:", parseError, text);
        setError('Market stream corrupted. Please retry.');
      }
    } catch (err) {
      console.error("Prediction Error:", err);
      setError('An error occurred. Please try again.');
    } finally {
      setIsLoading(false);
    }
  }, [selectedGame]);

  const handleSendMessage = useCallback(async (text: string) => {
    if (!chat) return;

    const userMsg: ChatMessage = { role: 'user', content: text };
    setMessages(prev => [...prev, userMsg]);
    setIsReplying(true);
    setShowSuggestions(false);

    try {
        const response = await chat.sendMessage({ message: text });
        const responseText = response.text || "I couldn't generate a response.";
        const modelMsg: ChatMessage = { role: 'model', content: responseText };
        setMessages(prev => [...prev, modelMsg]);
    } catch (error) {
        console.error("Chat Error:", error);
        setMessages(prev => [...prev, { role: 'model', content: "Sorry, I encountered an error." }]);
    } finally {
        setIsReplying(false);
    }
  }, [chat]);

  return (
    <div className="min-h-screen bg-black text-white font-sans selection:bg-amber-500/30 overflow-x-hidden">
      <Header onOpenSettings={handleOpenSettings} onOpenToken={handleOpenToken} />

      <main className={`container mx-auto px-4 py-6 max-w-4xl relative z-0 transition-all duration-500 ${isHistorySidebarOpen && pickSlip.length > 0 ? 'pr-[300px]' : ''}`}>

        {error && (
            <div className="bg-red-900/50 border border-red-500/50 text-red-200 px-4 py-3 rounded-xl mb-6 flex items-center justify-between animate-fade-in">
                <span>{error}</span>
                <button onClick={() => setError(null)} className="text-red-400 hover:text-white">&times;</button>
            </div>
        )}

        {!prediction && messages.length === 0 && !isLoading ? (
            <div className="space-y-8 animate-fade-in">
                <SportSelector selectedSport={selectedSport} onSelectSport={setSelectedSport} />
                <GameSchedule 
                    sport={selectedSport}
                    selectedGame={selectedGame}
                    onSelectGame={(game) => {
                        setSelectedGame(game);
                        setError(null);
                    }}
                />

                {selectedGame && (
                    <div className="fixed bottom-6 left-0 right-0 p-4 flex justify-center z-20 pointer-events-none">
                         <button
                            onClick={handlePredict}
                            className="pointer-events-auto bg-gradient-to-r from-amber-500 via-orange-500 to-amber-600 text-black font-black text-lg py-4 px-12 rounded-full shadow-[0_0_40px_rgba(245,158,11,0.5)] hover:shadow-[0_0_60px_rgba(245,158,11,0.7)] transform hover:scale-105 transition-all duration-300 flex items-center gap-2 group"
                        >
                            <svg className="w-6 h-6 group-hover:animate-pulse" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
                            GENERATE PROFIT MODELS
                        </button>
                    </div>
                )}
            </div>
        ) : isLoading ? (
            <Loader />
        ) : (
            <div className="space-y-4 animate-fade-in">
                 <button 
                    onClick={() => {
                        setPrediction(null);
                        setMessages([]);
                        setChat(null);
                    }}
                    className="flex items-center gap-2 text-stone-400 hover:text-white mb-2 transition-colors"
                 >
                    <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7m0 0l7-7m-7 7h18" /></svg>
                    Back to Schedule
                 </button>

                 <ChatInterface 
                    messages={messages}
                    isReplying={isReplying}
                    onSendMessage={handleSendMessage}
                    oddsFormat={settings.oddsFormat}
                    onAnalyzeProp={(prop) => handleSendMessage(`Deep dive analysis for ${prop.player} ${prop.stat}. compare lines between all books and show last 5 game trends.`)}
                    pickSlip={pickSlip}
                    onTogglePick={handleTogglePick}
                    onSearchPlayer={(player) => handleSendMessage(`Analyze ${player}'s highest hit-rate prop for today. compare PrizePicks, Betr, and Underdog.`)}
                 />

                 {showSuggestions && prediction && (
                    <SuggestionChips prediction={prediction} onSelect={handleSendMessage} />
                 )}
            </div>
        )}
      </main>

      <PerformanceSidebar 
        activePicks={pickSlip} 
        onClose={() => setIsHistorySidebarOpen(false)}
      />

      <PickSlip 
        picks={pickSlip} 
        onRemove={handleRemoveFromSlip}
        onAnalyze={() => handleSendMessage(`Analyze my current slip: ${pickSlip.map(p => `${p.player} ${p.type} ${p.line} ${p.stat}`).join(', ')}. Check for negative correlation and Combined win %`)}
      />

      <Footer />
      <SettingsModal 
        isOpen={isSettingsOpen} 
        onClose={handleCloseSettings} 
        currentSettings={settings}
        onSave={handleSaveSettings}
      />
      <TokenomicsModal 
        isOpen={isTokenModalOpen}
        onClose={handleCloseToken}
      />
    </div>
  );
};

export default App;
